import{_ as l,c as p,o as a,ae as o}from"./chunks/framework.CDAOyxyO.js";const m=JSON.parse('{"title":"Описание проекта GPUI","description":"","frontmatter":{},"headers":[],"relativePath":"projects/alt-domain/gpui/index.md","filePath":"projects/alt-domain/gpui/index.md"}'),e={name:"projects/alt-domain/gpui/index.md"};function t(u,i,r,n,s,d){return a(),p("div",null,i[0]||(i[0]=[o('<h1 id="описание-проекта-gpui" tabindex="-1">Описание проекта GPUI <a class="header-anchor" href="#описание-проекта-gpui" aria-label="Permalink to &quot;Описание проекта GPUI&quot;">​</a></h1><p>GPUI — модуль редактирования политик групповой конфигурации (Group Policy UI), часть инструментария администрирования Active Directory в ALT Linux.</p><p>GPUI — это графический модуль для просмотра и редактирования политик групповой конфигурации (Group Policy ) в системах на основе Samba / Active Directory , разработанный как часть инструментария администрирования ADMC (ALT Domain Management Console) в дистрибутиве ALT Linux.</p><h2 id="цель-проекта" tabindex="-1">Цель проекта <a class="header-anchor" href="#цель-проекта" aria-label="Permalink to &quot;Цель проекта&quot;">​</a></h2><p>Целью проекта является обеспечение удобного, безопасного и функционального способа управления настройками политик Active Directory / Samba-домена через графический интерфейс, без необходимости использования Windows-инструментов или глубокого знания внутреннего устройства POL-файлов.</p><h2 id="задачи" tabindex="-1">Задачи <a class="header-anchor" href="#задачи" aria-label="Permalink to &quot;Задачи&quot;">​</a></h2><ol><li><p>Редактирование политик</p><ul><li>Создание, изменение и удаление политик пользователей и компьютеров.</li><li>Поддержка административных шаблонов (ADMX/ADML).</li><li>Управление скриптами входа/выхода.</li><li>Работа с предпочтениями: файлы, папки, реестр, принтеры и т.д.</li></ul></li><li><p>Локализация и мультиязычность</p><ul><li>Полная поддержка перевода интерфейса на русский язык.</li><li>Автоматическое определение языка системы.</li><li>Возможность добавления новых локалей без перекомпиляции приложения.</li></ul></li><li><p>Интеграция с LAPS</p><ul><li>Позволяет отображать и управлять паролями локального администратора через GPO.</li><li>Поддерживает работу с атрибутами msDS-*, связанными с LAPS.</li></ul></li><li><p>Совместимость с Samba</p><ul><li>Актуальная поддержка последних версий Samba 4.20+ .</li><li>Исправление ошибок работы с дескрипторами безопасности, POL-файлами и другими компонентами Samba.</li></ul></li><li><p>Безопасное делегирование</p><ul><li>Позволяет пользователям с ограниченными правами работать с политиками, если они имеют соответствующие делегированные разрешения.</li><li>Проверка доступа по SID вместо имени группы.</li></ul></li><li><p>Отладка и логирование</p><ul><li>Добавлен подробный вывод действий и ошибок.</li><li>Интеграция механизмов отката изменений.</li><li>Замена модальных окон на системные сообщения.</li></ul></li><li><p>Удобство использования</p><ul><li>Визуальные индикаторы состояния политик: &quot;включена&quot;, &quot;отключена&quot;, &quot;наследуется&quot;.</li><li>Поддержка drag &amp; drop для изменения порядка политик.</li><li>Фильтры и поиск политик по OU и категориям.</li></ul></li><li><p>Работа с POL-файлами</p><ul><li>Полный цикл чтения и сохранения .pol файлов.</li><li>Поддержка их корректной обработки и восстановления.</li></ul></li><li><p>Техническая стабильность</p><ul><li>Исправление сегфолтов, гонок, утечек памяти.</li><li>Тестирование в различных условиях и средах.</li><li>Совместимость с E2K, Sisyphus и другими сборками ALT Linux.</li></ul></li></ol><h2 id="преимущества" tabindex="-1">Преимущества <a class="header-anchor" href="#преимущества" aria-label="Permalink to &quot;Преимущества&quot;">​</a></h2><ol><li><p>Полностью на русском</p><p>Интерфейс и документация поддерживают русский язык, что особенно важно для государственных и корпоративных клиентов.</p></li><li><p>Независимость от Windows</p><p>Полностью заменяет RSAT и GPMC, позволяя управлять политиками из ALT Linux.</p></li><li><p>Поддержка современных стандартов</p><p>Совместим с Samba 4.20+, ADMX/ADML, LAPS, UTF-16LE, D-Bus, systemd.</p></li><li><p>Модульная архитектура</p><p>Легко расширяемая система плагинов для новых типов политик.</p></li><li><p>Дружелюбный интерфейс</p><p>Чистый GUI, автозаполнение, tooltips, эллипсис для длинных названий.</p></li><li><p>Безопасность и делегирование</p><p>Возможность работы с политиками без членства в группе Domain Admins.</p></li><li><p>Интеграция с ADMC</p><p>Работает как отдельно, так и в составе основной консоли управления доменом.</p></li><li><p>Открытый исходный код</p><p>Распространяется под лицензией GPLv2+.</p></li></ol><h2 id="целевая-аудитория-проекта-gpui" tabindex="-1">Целевая аудитория проекта GPUI: <a class="header-anchor" href="#целевая-аудитория-проекта-gpui" aria-label="Permalink to &quot;Целевая аудитория проекта GPUI:&quot;">​</a></h2><ul><li>Системные администраторы , работающие с доменной инфраструктурой на базе Samba/Active Directory .</li><li>IT-специалисты , внедряющие и эксплуатирующие ALT Linux в корпоративной среде.</li><li>Конечные пользователи , которым требуется удобный GUI для редактирования политик.</li><li>Разработчики свободного ПО , желающие участвовать в создании полноценного аналога RSAT.</li></ul><h2 id="проект-gpui-решает-следующие-проблемы" tabindex="-1">Проект GPUI решает следующие проблемы: <a class="header-anchor" href="#проект-gpui-решает-следующие-проблемы" aria-label="Permalink to &quot;Проект GPUI решает следующие проблемы:&quot;">​</a></h2><ol><li><p>Сложности с редактированием политик в Samba</p><p>GPUI предоставляет понятный GUI, полностью заменяющий GPMC и RSAT.</p></li><li><p>Нужно использовать Windows для управления политиками</p><p>Теперь можно управлять политиками из ALT Linux без сторонних Windows-инструментов.</p></li><li><p>Отсутствие локализации интерфейса</p><p>Русский язык реализован во всех элементах: от кнопок до справочных материалов.</p></li><li><p>Ошибки при работе с POL-файлами</p><p>Полностью переписан и протестирован парсер POL-файлов.</p></li><li><p>Нестабильная работа с LDAP/SMB</p><p>Исправлены ошибки с путями GUID, драйверами, кодировкой и сетевыми ресурсами.</p></li><li><p>Невозможность делегировать права на редактирование политик</p><p>Реализована проверка прав по SID, что позволяет не быть членом группы &quot;Domain Admins&quot;.</p></li><li><p>Баги и краши при редактировании политик</p><p>Введены тесты, исправлены утечки памяти и гонки потоков.</p></li><li><p>Неудобное управление списками и флагами</p><p>Реализованы удобные виджеты и поля ввода, включая QComboBox, QSpinBox, QLineEdit и т.д.</p></li><li><p>Нет возможности просмотра дескрипторов безопасности в SDDL</p><p>Добавлено отображение дескрипторов и возможность отката к предыдущему состоянию.</p></li><li><p>Политики теряются после применения изменений</p><p>Добавлены механизмы отслеживания изменений и запрос на сохранение.</p></li><li><p>Долгое время невозможно было собирать GPUI на новых платформах</p><p>Исправлены сборки под E2K и Sisyphus, обновлены зависимости.</p></li></ol>',13)]))}const P=l(e,[["render",t]]);export{m as __pageData,P as default};
